## ⚙️ script.js

```javascript
document.addEventListener("DOMContentLoaded", () => {
    const opcaoPagamento = document.getElementById("opcaoPagamento");
    const btnInformarDados = document.getElementById("btnInformarDados");
    const painelPix = document.getElementById("painelPix");
    const painelCartao = document.getElementById("painelCartao");
    const numeroCardao = document.getElementById("numeroCardao");
    const iconeBandeira = document.getElementById("iconeBandeira");
    const parcelas = document.getElementById("parcelas");
    const valorInicial = parseFloat(document.querySelector(".valor-inicial").value || "0");

    // Valor fictício da compra para cálculo (exemplo: R$ 100,00)
    document.querySelector(".valor-inicial").value = "100.00";

    let valorAtual = valorInicial;

    // ---------- Mostrar/Ocultar painéis ----------
    opcaoPagamento.addEventListener("change", () => {
        if (opcaoPagamento.value === "pix") {
            painelPix.classList.remove("oculto");
            painelCartao.classList.add("oculto");
            resetarCamposCartao();
        } else {
            painelCartao.classList.remove("oculto");
            painelPix.classList.add("oculto");
            aplicarValidacaoNumero();
        }
    });

    // ---------- Botão "Informar dados" ----------
    btnInformarDados.addEventListener("click", () => {
        if (!document.getElementById("formPagamento").checkValidity()) {
            // Validação simples: campo obrigatório do select
            const select = document.getElementById("opcaoPagamento");
            if (!select.value) {
                showErro("Por favor, selecione uma forma de pagamento.");
                select.focus();
                return;
            }
        }

        const select = document.getElementById("opcaoPagamento");
        if (select.value === "pix") {
            mostrarPainelPix();
        } else {
            mostrarPainelCartao();
        }
    });

    function showErro(msg) {
        document.getElementById("msgErro").textContent = msg;
        document.getElementById("msgErro").style.display = "block";
        setTimeout(() => {
            document.getElementById("msgErro").style.display = "none";
        }, 4000);
    }

    function mostrarPainelPix() {
        atualizarTotalPix();
    }

    function mostrarPainelCartao() {
        aplicarValidacaoNumero();
    }

    // ---------- Cálculo Pix: 10% de desconto ----------
    function atualizarTotalPix() {
        const total = valorInicial * 0.90;
        document.getElementById("pixTotal").textContent = total.toFixed(2);
        document.getElementById("cartaoTotal").textContent = "—";
    }

    // ---------- Cálculo Cartão: parcelamento ----------
    function calcularParcelas(selecao) {
        const qtd = parseInt(selecao.value, 10);
        let valorParcela = valorInicial;
        let jurosPercentual = 0;
        let total;

        if (qtd <= 3) {
            // sem juros
            const parcela = valorInicial / qtd;
            valorParcela = parcela;
            total = valorInicial;
        } else if (qtd === 4) {
            jurosPercentual = 0.05;
            const base = valorInicial * (1 + jurosPercentual);
            total = base;
            valorParcela = total / qtd;
        } else if (qtd === 5) {
            jurosPercentual = 0.10;
            const base = valorInicial * (1 + jurosPercentual);
            total = base;
            valorParcela = total / qtd;
        } else {
            total = valorInicial;
            valorParcela = total / qtd;
        }

        document.getElementById("cartaoTotal").textContent = total.toFixed(2);
        // opcional: mostrar valor da parcela
        const pText = document.createElement("small");
        pText.id = "valorParcela";
        pText.style.marginTop = "6px";
        pText.style.color = "#555";
        pText.textContent = `Valor da parcela: R$ ${valorParcela.toFixed(2)}`;
        document.querySelector(".cartao-total").appendChild(pText);
    }

    parcelas.addEventListener("change", () => {
        calcularParcelas(parcelas.selectedOption);
    });

    // ---------- Validação do número do cartão ----------
    numeroCardao.addEventListener("input", () => {
        aplicarValidacaoNumero();
    });

    function aplicarValidacaoNumero() {
        const valor = numeroCardao.value.replace(/\s/g, "").replace(/[^0-9]/g, "");

        // Limite de dígitos típico (16)
        if (valor.length > 16) {
            numeroCardao.value = "";
            iconeBandeira.innerHTML = "";
            showErro("O número do cartão não pode ter mais de 16 dígitos.");
            return;
        }

        // Reset mensagens
        document.getElementById("msgErro").style.display = "none";
        iconeBandeira.innerHTML = "";

        if (!valor || valor.length < 4) {
            return; // ainda não há dígitos suficientes
        }

        const inicio = valor.substring(0, 4);

        if (inicio === "1234") {
            iconeBandeira.innerHTML = '<span class="icone-bandeira icone-visa"></span>';
        } else if (inicio === "4321") {
            iconeBandeira.innerHTML = '<span class="icone-bandeira icone-mastercard"></span>';
        } else {
            showErro("Número de cartão inválido.");
        }
    }

    function resetarCamposCartao() {
        numeroCardao.value = "";
        vencimento.value = "";
        cvv.value = "";
        parcelas.selectedIndex = 0;
        calcularParcelas(parcelas.selectedOption);
        iconeBandeira.innerHTML = "";
        document.getElementById("valorParcela").remove();
    }

    // ---------- Botão Pagar ----------
    document.getElementById("btnPagarPix").addEventListener("click", pagar);
    document.getElementById("btnPagarCartao").addEventListener("click", pagar);

    function pagar() {
        // Validação mínima antes de aceitar
        const form = document.getElementById("formPagamento");
        const valid = form.checkValidity();

        if (!valid) {
            const err = form.querySelector(":invalid:not([type='submit'])");
            if (err) {
                err.focus();
                showErro("Corrija os campos destacados antes de pagar.");
                return;
            }
            showErro("Preencha todos os dados necessários primeiro.");
            return;
        }

        // Ocultar qualquer mensagem anterior
        document.getElementById("msgErro").style.display = "none";
        document.getElementById("msgSucesso").style.display = "none";

        // Simular processamento
        const btn = document.querySelectorAll(".btn-pagar")[0];
        const originalText = btn.textContent;
        btn.textContent = "Processando...";
        btn.disabled = true;

        setTimeout(() => {
            document.getElementById("msgSucesso").textContent = "✅ Pagamento realizado com sucesso!";
            document.getElementById("msgSucesso").style.display = "block";
            btn.textContent = originalText;
            btn.disabled = false;
        }, 2000);
    }
});
